def match(orders):
    trades = []

    # Resting orders: buy_book[price] = [(arrival_time, id, qty), ...], sell_book[price] = [...]
    buy_book = {}  # price -> list of (arrival_time, id, qty)
    sell_book = {}  # price -> list of (arrival_time, id, qty)

    # Track state of each order
    order_state = {}  # id -> {'type': 'limit'/'ioc'/'market', 'remaining': qty, 'resting_at': (book, price, index)}

    arrival_time_counter = 0

    for order in orders:
        arrival_time_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_state:
                state = order_state[order_id]
                if 'resting_at' in state:
                    book, price, idx = state['resting_at']
                    if price in book and idx < len(book[price]) and book[price][idx][1] == order_id:
                        book[price].pop(idx)
                        if not book[price]:
                            del book[price]
                    del order_state[order_id]
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]
        qty = order[3] if order_type == 'market' else order[4]
        price = order[3] if order_type != 'market' else None

        remaining = qty

        if side == 'buy':
            # Match against sell orders
            while remaining > 0:
                # Find best sell: lowest price, then earliest arrival
                best_price = None
                best_idx = None

                for sell_price in sorted(sell_book.keys()):
                    if sell_price <= price or order_type == 'market':
                        if sell_book[sell_price]:
                            best_price = sell_price
                            best_idx = 0
                            break

                if best_price is None:
                    break

                arrival, sell_id, sell_qty = sell_book[best_price][best_idx]
                trade_qty = min(remaining, sell_qty)

                trades.append([order_id, sell_id, best_price, trade_qty])

                remaining -= trade_qty
                sell_book[best_price][best_idx] = (arrival, sell_id, sell_qty - trade_qty)

                if sell_book[best_price][best_idx][2] == 0:
                    sell_book[best_price].pop(best_idx)
                    if not sell_book[best_price]:
                        del sell_book[best_price]
                    if sell_id in order_state:
                        del order_state[sell_id]
                else:
                    order_state[sell_id]['remaining'] = sell_qty - trade_qty

        else:  # side == 'sell'
            # Match against buy orders
            while remaining > 0:
                # Find best buy: highest price, then earliest arrival
                best_price = None
                best_idx = None

                for buy_price in sorted(buy_book.keys(), reverse=True):
                    if buy_price >= price or order_type == 'market':
                        if buy_book[buy_price]:
                            best_price = buy_price
                            best_idx = 0
                            break

                if best_price is None:
                    break

                arrival, buy_id, buy_qty = buy_book[best_price][best_idx]
                trade_qty = min(remaining, buy_qty)

                trades.append([buy_id, order_id, best_price, trade_qty])

                remaining -= trade_qty
                buy_book[best_price][best_idx] = (arrival, buy_id, buy_qty - trade_qty)

                if buy_book[best_price][best_idx][2] == 0:
                    buy_book[best_price].pop(best_idx)
                    if not buy_book[best_price]:
                        del buy_book[best_price]
                    if buy_id in order_state:
                        del order_state[buy_id]
                else:
                    order_state[buy_id]['remaining'] = buy_qty - trade_qty

        # Add remainder to book if limit order
        if order_type == 'limit' and remaining > 0:
            if side == 'buy':
                if price not in buy_book:
                    buy_book[price] = []
                buy_book[price].append((arrival_time_counter, order_id, remaining))
                order_state[order_id] = {
                    'type': 'limit',
                    'remaining': remaining,
                    'resting_at': (buy_book, price, len(buy_book[price]) - 1)
                }
            else:  # sell
                if price not in sell_book:
                    sell_book[price] = []
                sell_book[price].append((arrival_time_counter, order_id, remaining))
                order_state[order_id] = {
                    'type': 'limit',
                    'remaining': remaining,
                    'resting_at': (sell_book, price, len(sell_book[price]) - 1)
                }
        elif remaining == 0:
            order_state[order_id] = {'type': order_type, 'remaining': 0}

    return trades

